import ast,sys
for f in ("../wc_plus.py","../test_wc_plus.py"):
    t=ast.parse(open(f).read())
    mods=set()
    for n in ast.walk(t):
        if isinstance(n,ast.Import):
            mods.update(a.name.split('.')[0] for a in n.names)
        elif isinstance(n,ast.ImportFrom) and n.module:
            mods.add(n.module.split('.')[0])
    print(f, sorted(mods), "non-stdlib:", sorted(m for m in mods if m not in sys.stdlib_module_names and m not in ("wc_plus",)))
EOF
